/**
 * UNSPSC Family/Class/Commodity -- Reference (registry #385, ISC Services
 * Classification Book v1.3, lowest-level import)
 *
 * The Family (4-digit), Class (6-digit), and Commodity (8-digit) levels of
 * the United Nations Standard Products and Services Code, for the same 16
 * services segments already covered by UNSPSC_SERVICES_SEGMENTS in
 * unspscSegments.ts. Sourced 28 Aug 2026 directly from the UNDP's own
 * primary distribution -- unspsc-english-v260801.1.xlsx, version UNv260801,
 * downloaded by the owner from undp.org/unspsc and relayed in (this
 * session's sandboxed build environment cannot reach undp.org directly --
 * outbound network is allowlisted and that domain isn't on it) -- NOT the
 * third-party mirror (usa.databasesets.com) the book's earlier Family-level
 * partial lists were sourced from on 24 Aug 2026. Where this file and the
 * book's earlier partial lists overlap, they agree; this file is simply
 * complete where the earlier pass was partial (see
 * isc-services-classification-book-v1.md, "Parent level (Family)" section
 * and Open Items #3 for the full provenance and the corrected
 * administrator/licensing history -- UNSPSC moved from GS1 US to direct
 * UNDP administration on 1 Jan 2025, and the full codeset is a free
 * download, not a paid license).
 *
 * Scope: only the 16 services segments this book covers (70, 71, 72, 73,
 * 76, 77, 78, 80, 81, 82, 83, 84, 90, 91, 92, 93) -- goods segments
 * (10-69 range) are intentionally excluded, same scope boundary as
 * unspscSegments.ts. 96 families, 506 classes, 3,660 commodities.
 *
 * Titles only -- the source file's Segment/Family/Class/Commodity
 * Definition columns (long-form descriptive text) are not carried into
 * this file; Titles alone are what the existing Segment-level UI pattern
 * uses, and definitions can be added later from the same source file
 * without a new fetch if a future pass wants them.
 *
 * Arabic labels are NOT included here (unlike UNSPSC_SERVICES_SEGMENTS'
 * 16 hand-translated segment labels) -- machine-translating 3,660+ official
 * taxonomy terms without a qualified bilingual review would risk shipping
 * plausible-looking but unverified Arabic text, which this engagement's
 * "never fake it" standard (Decision Record 8.7) does not allow. English
 * only, honestly, until a real Arabic pass is scoped.
 */

export interface UnspscCommodity {
  code: string;   // 8-digit UNSPSC commodity code
  title: string;
}

export interface UnspscClass {
  code: string;   // 6-digit UNSPSC class code (trailing 00)
  title: string;
  commodities: UnspscCommodity[];
}

export interface UnspscFamily {
  code: string;   // 4-digit UNSPSC family code (trailing 0000)
  title: string;
  classes: UnspscClass[];
}

